import{z as o,x as l,o as e,c as s,q as t,j as r,D as E,d as B,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"随机波动率的校准深入","description":"","frontmatter":{"title":"随机波动率的校准深入","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-sv-calibration-deep.md","filePath":"quant/vt-sv-calibration-deep.md","lastUpdated":1791063341000}'),h={name:"quant/vt-sv-calibration-deep.md"};function d(p,a,D,u,c,C){const A=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="随机波动率的校准深入" tabindex="-1">随机波动率的校准深入 <a class="header-anchor" href="#随机波动率的校准深入" aria-label="Permalink to &quot;随机波动率的校准深入&quot;">​</a></h1><div class="epigraph"><p>校准不是拟合比赛：正则与权重是建模选择，它们决定你的参数隔夜跳多少，从而决定你的希腊字母信不信得过。</p><footer>—— 据 Gatheral and Jacquier, 2014；Hagan et al., 2002 整理</footer></div><p><a href="/quant/vt-product-hedging">上一课</a>的对冲价由模型给出；模型从校准来。原理课有 <a href="/quant/heston">Heston</a>、<a href="/quant/sabr-calib">SABR 校准</a>与 <a href="/quant/svi-ssvi">SVI/SSVI</a>，工程课有<a href="/quant/calibration-global-opt">全局优化在校准</a>与<a href="/quant/calibration-regularization">校准正则化</a>。本课把它们装进一条生产管线，聚焦随机波动族的校准深入：选型、加权、稳定、诊断——校准到什么，就等于对冲到什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Heston 五参数不可正交识别：\\(v_0\\) 与 \\(\\theta\\) 管水平、\\(\\kappa\\) 管期限结构、\\(\\sigma\\) 管曲率、\\(\\rho\\) 管偏斜，但短端偏斜与长端水平会互相借用参数，同一张曲面有整族等价解。单到期可以贴得很漂亮，跨到期与隔夜稳定性一塌糊涂；每天重校准又让希腊字母跟着参数抖。没有管线约束的校准，输出的是每天换一个模型的幻觉稳定。<span class="marginnote">「校准」就是反着用模型：正着算是拿参数算出期权价格，反着算是拿着市场报价倒推参数。麻烦在于市场只给几十个报价，模型却有几个互相纠缠的自由参数——答案不是唯一的一个点，而是「都能贴出同一张曲面」的一整族解，必须靠额外规则从中挑一个。</span></p><h3 id="管线五段" tabindex="-1">管线五段 <a class="header-anchor" href="#管线五段" aria-label="Permalink to &quot;管线五段&quot;">​</a></h3><p>一、报价清洗与权重：坏价剔除后用 Vega 加权或价格域加权保护平值——权重表决定解往哪里偏，要和对冲手册放同一页。二、选型分工：Heston 给期限结构与仿射特征函数快价（<a href="/quant/heston-cf">heston-cf</a>），<a href="/quant/bates">Bates</a> 的跳补短端偏斜，SVI/SSVI 管单切片与跨期一致性（<a href="/quant/svi-arb-params">SVI 无套利参数化</a>、<a href="/quant/ssvi-term-consistency">SSVI 期限结构一致性</a>），<a href="/quant/bergomi">Bergomi</a> 与 <a href="/quant/rough-bergomi">rBergomi</a> 管曲线动态与陡短偏斜。没有万能参数化，只有按产品分工。三、优化：全局搜索防局部极小；正则项把「对昨日参数的距离」写进目标函数，正则强度是风控参数，不是拟合参数。四、快价与模拟：仿射族走傅里叶反演，Bergomi 族只能模拟，模拟规格属于模型定义。五、诊断：蝶式与日历扫描、残差热图、<a href="/quant/heston-feller">Feller 条件</a>检查、隔夜参数漂移曲线。</p>',7)),(e(),r(i,null,{default:E(()=>[n(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%A5%E4%BB%B7%E6%B8%85%E6%B4%97%E4%B8%8E%E6%9D%83%E9%87%8D%22%5D%20--%3E%20SEL%7B%22%E9%80%89%E5%9E%8B%E5%88%86%E5%B7%A5%22%7D%0A%20%20SEL%20--%3E%7C%22%E6%9C%9F%E9%99%90%E4%B8%8E%E5%BF%AB%E4%BB%B7%22%7C%20HEST%5B%22Heston%20%2F%20Bates%22%5D%0A%20%20SEL%20--%3E%7C%22%E5%8D%95%E5%88%87%E7%89%87%E4%B8%8E%E4%B8%80%E8%87%B4%E6%80%A7%22%7C%20SVI%5B%22SVI%20%2F%20SSVI%22%5D%0A%20%20SEL%20--%3E%7C%22%E6%9B%B2%E7%BA%BF%E5%8A%A8%E6%80%81%22%7C%20BERG%5B%22Bergomi%20%2F%20rBergomi%22%5D%0A%20%20HEST%20--%3E%20OPT%5B%22%E5%85%A8%E5%B1%80%E6%90%9C%E7%B4%A2%E5%8A%A0%E6%AD%A3%E5%88%99%22%5D%0A%20%20SVI%20--%3E%20OPT%0A%20%20BERG%20--%3E%20OPT%0A%20%20OPT%20--%3E%20DIAG%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E8%9D%B6%E5%BC%8F%20%E6%97%A5%E5%8E%86%20Feller%20%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20DIAG%20--%3E%7C%22%E9%9A%94%E5%A4%9C%E6%BC%82%E7%A7%BB%E5%8F%8D%E9%A6%88%22%7C%20OPT%0A%20%20DIAG%20--%3E%20PUB%5B%22%E5%8F%91%E5%B8%83%E4%B8%8E%E5%86%BB%E7%BB%93%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断的验收标准先于拟合优度：蝶式扫描不许出负密度，日历扫描不许出总方差倒挂，残差热图不许在某个执行价带上长期同号。三项过了再看误差平方和——顺序反了，拟合越好病越重。稳定性用一条可执行指标：隔夜参数相对变化超过正则带宽的天数占比。占比高说明目标函数里等价解太多，先加正则再谈模型升级；多数「模型不行」的诊案，病根在目标函数而不是模型族。<span class="marginnote">初学者容易以为误差平方和最小就是校准最好。实际上误差小只说明「今天贴得像」，不保证「明天参数不跳」；蝶式、日历、残差三扫描都通过的低误差解，才敢拿去算对冲手数。顺序反了，拟合越漂亮病得越重。</span></p><p><span class="marginnote">Heston 的 \\(\\kappa\\) 调大、\\(\\theta\\) 调小可以在形状几乎不变的情况下把长端压平，参数悄悄漂出 Feller 边界。此时模拟必须显式声明边界规则，否则隔夜 PnL 归因指向的是一个不存在的模型——检查条件比检查拟合更要紧。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>校准是反问题：数据有限而参数自由，正则决定解落在解族的哪里。每天重校准等于隐式换模型：希腊字母的不稳定多半不是模型错，而是正则太弱让参数在等价解之间游走。权重的传导同样直接：给平值高权重的解，平值对冲就稳、翼部对冲就漂——「校准到什么就等于对冲到什么」是本课的机制核心，权重表因此属于风控文档，不属于研究附件。</p>',5)),(e(),r(i,null,{default:E(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%B3%A2%E5%8A%A8%E7%8E%87%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20F%5B%22%E5%8F%8D%E9%97%AE%E9%A2%98%EF%BC%9A%E6%95%B0%E6%8D%AE%E6%9C%89%E9%99%90%20%E5%8F%82%E6%95%B0%E8%87%AA%E7%94%B1%22%5D%0A%20%20F%20--%3E%20EQ%5B%22%E6%95%B4%E6%97%8F%E7%AD%89%E4%BB%B7%E8%A7%A3%20%E5%BD%A2%E7%8A%B6%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20EQ%20--%3E%20Q%7B%22%E6%AD%A3%E5%88%99%E5%BC%BA%E5%BA%A6%E6%80%8E%E4%B9%88%E5%AE%9A%22%7D%0A%20%20Q%20--%3E%7C%22%E5%A4%AA%E5%BC%B1%22%7C%20W%5B%22%E5%8F%82%E6%95%B0%E9%9A%94%E5%A4%9C%E6%B8%B8%E8%B5%B0%20%E5%B8%8C%E8%85%8A%E5%AD%97%E6%AF%8D%E6%8A%96%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%88%E9%80%82%22%7C%20P%5B%22%E9%92%89%E5%9C%A8%E6%98%A8%E6%97%A5%E5%8F%82%E6%95%B0%E9%99%84%E8%BF%91%20%E5%B8%8C%E8%85%8A%E5%AD%97%E6%AF%8D%E7%A8%B3%22%5D%0A%20%20Q%20--%3E%7C%22%E5%A4%AA%E5%BC%BA%22%7C%20S%5B%22%E8%B4%B4%E5%B8%82%E5%9C%BA%E5%A4%AA%E6%85%A2%20%E6%AE%8B%E5%B7%AE%E5%8F%98%E5%A4%A7%22%5D%0A%20%20W%20--%3E%20RX%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E6%BC%82%E7%A7%BB%E8%B6%85%E5%B8%A6%E5%AE%BD%E5%A4%A9%E6%95%B0%E5%8D%A0%E6%AF%94%22%5D%0A%20%20RX%20--%3E%7C%22%E5%8D%A0%E6%AF%94%E9%AB%98%22%7C%20FIX%5B%22%E5%85%88%E5%8A%A0%E6%AD%A3%E5%88%99%20%E5%86%8D%E8%B0%88%E6%A8%A1%E5%9E%8B%E5%8D%87%E7%BA%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">正则项可以想象成给参数拴的风筝线：线太松，参数隔夜就随风飘到解族另一头，希腊字母跟着打摆；线太紧，模型又贴不上市场的真实变化。说「正则强度是风控参数」，意思是这根线的松紧决定的是风险大小，而不是拟合精度高低。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推特征函数与 Riccati 方程；<a href="/quant/lsv-hybrid-calib">局部-随机混合校准</a>是下一课的邻居；跨市场参数迁移（用外汇的 \\(\\rho\\) 猜股指）一律禁止。正则的贝叶斯解释一句带过：先验越强越稳、越弱越贴，选择要在压力测试里做，不在回测里挑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Heston 参数不可正交识别，等价解族要靠正则挑出一个稳定的。</li><li>选型按产品分工：仿射快价、跳补短端、SVI 管切片、Bergomi 管动态。</li><li>诊断先于拟合：蝶式、日历、残差三扫描不过，误差再小也不发布。</li><li>稳定性指标：隔夜参数漂移超正则带宽的天数占比，先加正则再升级模型。</li><li>权重表与正则强度是风控参数：校准到什么，就等于对冲到什么。</li><li>出处：Heston, 1993；Hagan et al., 2002；Gatheral and Jacquier, 2014；Bayer, Friz and Gatheral, 2016。</li></ul>',5))])}const f=o(h,[["render",d]]);export{_ as __pageData,f as default};
